#!/usr/bin/env python3
"""Install three presentation files only; never edits data, credentials or timers."""
import argparse,base64,datetime,fcntl,gzip,hashlib,json,os,pathlib,pwd,shutil,subprocess,tempfile,time,urllib.request,urllib.error
BUNDLE=''
APP=pathlib.Path('/opt/umraniye-osint-deneme');UNIT='umraniye-osint-deneme.service'
def safe(p):
 for q in [p,*p.parents]:
  if q.is_symlink():raise RuntimeError('symlink_path_rejected')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest() if p.exists() else None
def run(args):return subprocess.run(args,check=True,capture_output=True,text=True,timeout=120)
def write(p,data,meta):
 safe(p);fd,tmp=tempfile.mkstemp(prefix='.ui-',dir=p.parent)
 try:
  with os.fdopen(fd,'wb') as f:f.write(data);f.flush();os.fsync(f.fileno());os.fchmod(f.fileno(),meta['mode']);os.fchown(f.fileno(),meta['uid'],meta['gid'])
  os.replace(tmp,p)
 finally:pathlib.Path(tmp).unlink(missing_ok=True)
def health():
 try:
  with urllib.request.urlopen('http://127.0.0.1:3001/giris',timeout=4) as r:return r.status==200
 except Exception:return False
def restore(backup,manifest):
 for key,meta in manifest.items():
  p=APP/key
  if meta['existed']:write(p,(backup/'files'/key).read_bytes(),meta)
  else:p.unlink(missing_ok=True)
def main():
 parser=argparse.ArgumentParser();parser.add_argument('--apply',action='store_true');args=parser.parse_args()
 if os.geteuid()!=0:raise RuntimeError('sudo_required')
 lock=open('/run/osint-reviewed-release.lock','w');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 files=json.loads(gzip.decompress(base64.b64decode(BUNDLE)));user=pwd.getpwnam('osintdeneme')
 if all(sha(APP/k)==v['after'] for k,v in files.items()):print('{"result":"editorial_ui_already_installed"}');return
 for key,v in files.items():
  p=APP/key;safe(p)
  if sha(p)!=v['before']:raise RuntimeError('source_version_changed_no_install: '+key)
  if hashlib.sha256(base64.b64decode(v['content'])).hexdigest()!=v['after']:raise RuntimeError('payload_corrupt')
 if not health():raise RuntimeError('existing_application_unhealthy_no_install')
 if not args.apply:print('{"result":"editorial_ui_preflight_passed","files":3,"installed":false}');return
 root=pathlib.Path('/var/backups/umraniye-osint-reviewed');safe(root);root.mkdir(mode=0o700,exist_ok=True)
 if root.stat().st_uid!=0:raise RuntimeError('backup_root_not_owned_by_root')
 os.chmod(root,0o700);backup=root/('editorial-ui-'+datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ'));backup.mkdir(mode=0o700)
 manifest={}
 for key in files:
  p=APP/key;st=p.stat() if p.exists() else None;manifest[key]={'existed':bool(st),'uid':st.st_uid if st else user.pw_uid,'gid':st.st_gid if st else user.pw_gid,'mode':st.st_mode&0o777 if st else 0o644}
  if st:q=backup/'files'/key;q.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,q)
 (backup/'manifest.json').write_text(json.dumps(manifest));shutil.copy2(__file__,backup/'installer.py')
 rollback="""import importlib.util,pathlib,json,subprocess,fcntl
p=pathlib.Path(__file__).parent
s=importlib.util.spec_from_file_location('ui',p/'installer.py');m=importlib.util.module_from_spec(s);s.loader.exec_module(m)
lock=open('/run/osint-reviewed-release.lock','w');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
subprocess.run(['systemctl','stop',m.UNIT],check=True)
try:m.restore(p,json.loads((p/'manifest.json').read_text()))
finally:subprocess.run(['systemctl','start',m.UNIT],check=True)
print('Önceki arayüz geri yüklendi. Veritabanı değiştirilmedi.')
"""
 (backup/'geri-al.py').write_text(rollback)
 stopped=False;mutated=False
 try:
  stopped=True;run(['systemctl','stop',UNIT])
  for key,v in files.items():
   if sha(APP/key)!=v['before']:raise RuntimeError('source_changed_during_install')
  mutated=True
  for key,v in files.items():write(APP/key,base64.b64decode(v['content']),manifest[key])
  run(['systemctl','start',UNIT])
  for _ in range(40):
   if health():break
   time.sleep(1)
  else:raise RuntimeError('new_application_health_failed')
  print(json.dumps({'result':'editorial_ui_installed','changedFiles':list(files),'databaseChanged':False,'telegramChanged':False,'timersChanged':False,'collectionLogicChanged':False,'localApplicationVerified':True,'externalBrowserVerified':False,'backup':str(backup),'rollback':'sudo python3 '+str(backup/'geri-al.py')},ensure_ascii=False,indent=2))
 except Exception:
  if mutated:
   run(['systemctl','stop',UNIT]);restore(backup,manifest)
  if stopped:run(['systemctl','start',UNIT])
  raise
if __name__=='__main__':
 try:main()
 except Exception as e:print('KURULAMADI: '+str(e));raise SystemExit(1)
